import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 17 The longest suspension bridge in the world","description":"学习 最高级的范围与倍数，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 17 The longest suspension bridge in the world","description":"学习 最高级的范围与倍数，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 最高级的范围与倍数，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 16 Mary had a little lamb","link":"/life/english/new-concept/book-3/unit-01/lesson-016"},"next":{"text":"第三册：培养技能 · Lesson 18 Electric currents in modern art","link":"/life/english/new-concept/book-3/unit-01/lesson-018"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 16 Mary had a little lamb","link":"/life/english/new-concept/book-3/unit-01/lesson-016"},"next":{"text":"第三册：培养技能 · Lesson 18 Electric currents in modern art","link":"/life/english/new-concept/book-3/unit-01/lesson-018"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-017.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-017.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-017.md"};function l(s,e,r,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-17-the-longest-suspension-bridge-in-the-world" tabindex="-1">第三册：培养技能 · Lesson 17 The longest suspension bridge in the world <a class="header-anchor" href="#第三册-培养技能-·-lesson-17-the-longest-suspension-bridge-in-the-world" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 17 The longest suspension bridge in the world&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从大型桥梁的结构和尺度出发，练习准确比较工程对象。最高级需要清楚的比较范围，历史课名也不代表今天仍保持同一纪录。学习描述某一给定集合中的最大值、倍数和尺寸，避免混淆桥梁总长、主跨长度以及不同测量指标。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>span</td><td>/spæn/</td><td>n.</td><td>跨度</td><td>a central span</td></tr><tr><td>cable</td><td>/ˈkeɪbl/</td><td>n.</td><td>缆索</td><td>a steel cable</td></tr><tr><td>structure</td><td>/ˈstrʌktʃə/</td><td>n.</td><td>结构</td><td>a stable structure</td></tr><tr><td>length</td><td>/leŋθ/</td><td>n.</td><td>长度</td><td>the total length</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>at the time — 在当时，用于限定历史判断</li><li>as long as — 在长度比较中表示和……一样长，另有条件用法</li></ul><h2 id="语法讲解-最高级的范围与倍数" tabindex="-1">语法讲解：最高级的范围与倍数 <a class="header-anchor" href="#语法讲解-最高级的范围与倍数" aria-label="Permalink to &quot;语法讲解：最高级的范围与倍数&quot;">​</a></h2><p>形容词最高级通常带 the，并需要明确或可推知的比较范围，如 the longest bridge in this region。one of the 加最高级再加复数名词，谓语由 one 决定通常用单数。倍数可用 twice as long as 或 three times the length of；不要把 times more 与 times as 混用造成数值歧义。纪录随时间变化，描述历史纪录可使用 at the time。比较之前还应统一指标，否则即使语法正确，结论也可能把不同尺寸当成同一项目比较。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The new footbridge is twice as long as the wooden one it replaced.</p></blockquote><p>新的人行桥长度是被它替代的木桥的两倍。</p><p>twice as long as 表示明确倍数；one 替代 footbridge；it replaced 为省略宾语关系词的定语从句。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>one of the longest bridge 应为 one of the longest bridges；比较集合必须由复数名词表示。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 eighty 和 a hundred and sixty，再读 twice as long；听辨数字与倍数表达是否互相一致。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Bridge A has a central span of eighty metres. Bridge B&#39;s central span is twice as long. Among the three bridges in our model, Bridge B has the longest central span.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>给两座虚构桥梁写三句比较，注明指标和范围。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>三句使用同一指标 central span，并给出最高级的比较集合。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>旧桥长40米，例句中的新桥多长？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 80米。</p><p><strong>解析：</strong> twice as long 表示两倍长度。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：One of the tallest towers ___ closed.（is/are）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 主语中心为 One。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>为何介绍历史纪录时加 at the time？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 限定纪录成立的时间范围。</p><p><strong>解析：</strong> 避免暗示该纪录今天仍有效。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：最高级的范围与倍数。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-016">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-018">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
